"""Local stand-in for check.py (this container denies setsid/kill)."""
import json
import os
import resource
import selectors
import subprocess
import sys
import time
from pathlib import Path
sys.path.insert(0, '/workspace')
from audit import audit

WALL = 120
STDOUT = 64 * 1024 * 1024
STDERR = 1024 * 1024


def child_limits():
    for which, values in [
        (resource.RLIMIT_CPU, (180, 181)),
        (resource.RLIMIT_AS, (2 * 1024**3, 2 * 1024**3)),
        (resource.RLIMIT_NOFILE, (256, 256)),
        (resource.RLIMIT_NPROC, (64, 64)),
        (resource.RLIMIT_FSIZE, (64 * 1024**2, 64 * 1024**2)),
        (resource.RLIMIT_CORE, (0, 0)),
        (resource.RLIMIT_STACK, (8 * 1024**2, 8 * 1024**2)),
    ]:
        resource.setrlimit(which, values)


def run_child(entry, data, *, argv=None, raw=False, limits=True):
    env = dict(os.environ, PYTHONUNBUFFERED="1", PYTHONDONTWRITEBYTECODE="1",
               PYTHONHASHSEED="0", TMPDIR="/workspace/tmp")
    p = subprocess.Popen(argv or [sys.executable, "-B", str(entry)],
                         stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                         stderr=subprocess.PIPE, env=env, close_fds=True,
                         preexec_fn=child_limits if limits else None)
    selector = selectors.DefaultSelector()
    output = [bytearray(), bytearray()]
    offset = 0
    deadline = time.monotonic() + WALL
    code = None
    try:
        for stream in [p.stdin, p.stdout, p.stderr]:
            os.set_blocking(stream.fileno(), False)
        selector.register(p.stdin, selectors.EVENT_WRITE, -1)
        selector.register(p.stdout, selectors.EVENT_READ, 0)
        selector.register(p.stderr, selectors.EVENT_READ, 1)
        while selector.get_map():
            left = deadline - time.monotonic()
            if left <= 0:
                raise ValueError("child wall limit")
            for key, _ in selector.select(min(0.1, left)):
                stream, channel = key.fileobj, key.data
                if channel == -1:
                    if offset == len(data):
                        selector.unregister(stream)
                        stream.close()
                        continue
                    try:
                        offset += os.write(stream.fileno(), data[offset:offset + 65536])
                    except (BlockingIOError, BrokenPipeError):
                        pass
                else:
                    try:
                        chunk = os.read(stream.fileno(), 65536)
                    except BlockingIOError:
                        continue
                    if not chunk:
                        selector.unregister(stream)
                        stream.close()
                    else:
                        output[channel].extend(chunk)
        try:
            code = p.wait(timeout=max(0.001, deadline - time.monotonic()))
        except subprocess.TimeoutExpired:
            p.kill(); p.wait()
            raise ValueError("child wall limit")
        if code != 0:
            raise ValueError("child exited nonzero: %s" % output[1].decode()[:4000])
        return bytes(output[0]) if raw else json.loads(bytes(output[0]).decode())
    finally:
        selector.close()
        for stream in [p.stdin, p.stdout, p.stderr]:
            try:
                stream.close()
            except OSError:
                pass


def decode(data):
    def unique(pairs):
        out = {}
        for k, v in pairs:
            if k in out:
                raise ValueError("duplicate output key")
            out[k] = v
        return out

    def reject(value):
        raise ValueError("nonfinite JSON")

    return json.loads(data.decode("utf-8"), object_pairs_hook=unique,
                      parse_constant=reject)


def main(entry):
    entry = Path(entry).absolute()
    examples = Path('/workspace/examples')
    fails = 0
    for fixture in sorted(examples.glob("*.in.json")):
        expected = decode(fixture.with_name(
            fixture.name.replace(".in.", ".out.")).read_bytes())
        payload = fixture.read_bytes()
        actual = decode(run_child(entry, payload))
        try:
            request = decode(payload)
        except ValueError:
            request = None
        try:
            audit(request, actual, expected)
            print("json ok:", fixture.name)
        except Exception as exc:
            fails += 1
            print("json FAIL:", fixture.name, exc)
    binary = Path('/workspace/tmp') / 'local-engine'
    rc = run_child(entry, b'', argv=['g++', '-O2', '-std=c++17',
                                     str(entry / 'engine.cpp'), '-o', str(binary)],
                   raw=True)
    assert rc == b''
    for fixture in sorted(examples.glob("*.in.native")):
        expected = fixture.with_name(
            fixture.name.replace('.in.', '.out.')).read_bytes().split()
        actual = run_child(entry, fixture.read_bytes(), argv=[str(binary)],
                           raw=True).split()
        if actual != expected:
            fails += 1
            print("native FAIL:", fixture.name)
        else:
            print("native ok:", fixture.name)
    print("FAILURES:", fails)
    return 1 if fails else 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
